# -*- coding: utf-8 -*-
"""R77 S7 blind predictions generator. Segments append + per-segment asserts."""
import json, os

BASE = "/home/hatch/workspace/divination/benchmark/phase3/runs/round77/predictions"
os.makedirs(BASE, exist_ok=True)
TRIG = {"changed_main": False, "reserve_used": False, "disputed": False, "reason": ""}
_written = []

def flush(cases, expect_total):
    for cid, pred, basis, conf in cases:
        obj = {"case_id": cid, "prediction_text": pred, "basis": basis,
               "confidence": conf, "trigger": dict(TRIG)}
        with open(os.path.join(BASE, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(obj, f, ensure_ascii=False, indent=1)
        _written.append(cid)
    assert len(_written) == expect_total, (len(_written), expect_total)
    print("segment ok, total written:", len(_written))

